import functools

def retry(times):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            for _ in range(times - 1):
                try: return fn(*a, **kw)
                except Exception: pass
            return fn(*a, **kw)
        return wrapper
    return deco

